<?php
require __DIR__.'/lib.php';require_login();header('Cache-Control: private, no-store');$lock=null;$url='index.php?page=inflow&entry=manual';$lookup=false;
try{if($_SERVER['REQUEST_METHOD']==='GET'){if(!access_page_allowed('inflow'))throw new Exception('Return history access required.');$b=return_batch((int)($_GET['id']??0));$r=ur_export($b);$type=$_GET['download']??'';if($type==='print'){report_print_document($r['title'],$r['headers'],$r['rows'],['Batch'=>$b['batch_ref'],'Status'=>$b['status']]);exit;}if($type!=='xlsx')throw new Exception('Choose Excel or Print.');$tmp=tempnam(sys_get_temp_dir(),'unified-return-');try{report_write_xlsx($tmp,$r['title'],$r['headers'],$r['rows'],['Batch'=>$b['batch_ref'],'Status'=>$b['status']]);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="Unified_Return_'.$b['id'].'.xlsx"');readfile($tmp);}finally{if(is_file($tmp))unlink($tmp);}exit;}
 if($_SERVER['REQUEST_METHOD']!=='POST')throw new Exception('Use the return form.');verify_csrf();ur_require();$action=$_POST['action']??'';if($action==='ur_lookup'){$lookup=true;$r=ur_lookup($_POST['platform']??'',$_POST['order']??'');header('Content-Type: application/json');echo json_encode(['ok'=>true,'source'=>$r]);exit;}$lock=inventory_write_lock();
 if($action==='ur_stage'){$_SESSION['ur_form_draft']=$_POST;$id=ur_stage($_POST,$_FILES['attachment']??null);unset($_SESSION['ur_form_draft']);$url='index.php?page=manual_receiving&id='.$id;flash('Orders matched and organized. Complete receipt verification, then review the stock effect. No stock changed.','info');}
 else{$id=(int)($_POST['batch_id']??0);$b=return_batch($id);$url='index.php?page=manual_receiving&id='.$id;if($action==='ur_verify'){$_SESSION['ur_verify_draft'][$id]=$_POST;ur_verify($id,(int)($_POST['revision']??0),$_POST);unset($_SESSION['ur_verify_draft'][$id]);flash('Verification complete. Review and confirm the stock effect; no stock changed.','info');}elseif($action==='ur_post'){ur_owner($b);return_confirm($id,$_POST['digest']??'',!empty($_POST['review_ack']));flash('Actual return quantities posted once. History and reports are updated.');}elseif($action==='ur_cancel'){ur_owner($b);return_cancel($id);flash('Unposted batch cancelled. No stock added.');}elseif($action==='ur_link'){ur_link_original($id,(string)($_POST['order']??''));flash('Existing receipt linked to its original dispatch. No quantity added again.');}else throw new Exception('Unknown action.');}
}catch(Throwable $e){if($lookup||($_POST['action']??'')==='ur_lookup'){http_response_code(400);header('Content-Type: application/json');echo json_encode(['ok'=>false,'message'=>safe_error_message($e)]);exit;}if($_SERVER['REQUEST_METHOD']==='GET'){http_response_code(400);exit(e(safe_error_message($e)));}flash(safe_error_message($e),'danger');}finally{if($lock)inventory_write_unlock($lock);}header('Location: '.$url);exit;
